import {barBeats,totalBeats,getInstrument,notesFor,scoreProject,audibleTracks} from './catalog.js';
import {ART} from './instrument-art.js';
import {notationEvents,renderPatternScore} from './notation.js';
const W=1920,H=1080;
export function videoTiming(p,o){const seconds=60/p.bpm,title=o.title?3:0,count=o.countIn?barBeats(p)*seconds:0;return {seconds,title,count,prefix:title+count,musicStart:title+count+.02,musicEnd:title+count+.02+totalBeats(p)*seconds};}
export function videoMix(p,o){const copy=structuredClone(p);if(o.mode==='student'&&o.listening!=='ensemble')for(const t of copy.tracks){t.solo=false;t.muted=o.listening==='part'?t.id!==o.trackId:(t.id===o.trackId||t.muted)}return copy;}
export function videoState(p,o,time){const timing=videoTiming(p,o),beat=(time-timing.musicStart)/timing.seconds;return {...timing,beat,phase:time<timing.title?'title':time<timing.musicStart?'count':beat<totalBeats(p)?'music':'tail',measure:Math.max(0,Math.min(p.bars-1,Math.floor(beat/barBeats(p))))};}
// Constant-speed notation travel; never snap the score at measure boundaries.
export function videoScoreScroll(p,beat,pageWidth=800*270/220){return Math.max(0,Math.min(totalBeats(p),beat))/barBeats(p)*(pageWidth/2);}
export function videoPreviewProject(project){const p=structuredClone(project);p.bars=Math.min(4,p.bars);const end=totalBeats(p);p.tracks=p.tracks.map(t=>({...t,events:t.events.filter(e=>e.beat<end).map(e=>({...e,duration:Math.min(e.duration,end-e.beat)}))}));p.sectionMarkers=p.sectionMarkers?.filter(m=>m.beat<end);return p;}
export function videoStudentLayout(layout){return layout==='notation'?{instrumentHeight:270,image:[80,170,900,245],labelX:1040,labelY:225,labelWidth:740,scoreTop:450,scoreHeight:530,scoreY:510,notationHeight:396,anchor:300}:{instrumentHeight:450,image:[80,175,1250,405],labelX:1380,labelY:260,labelWidth:440,scoreTop:630,scoreHeight:350,scoreY:680,notationHeight:270,anchor:550};}
export function trimVideoPreviewAudio(buffer,p,createBuffer){const length=Math.min(buffer.length,Math.ceil((totalBeats(p)*60/p.bpm+1.5)*buffer.sampleRate));const out=createBuffer(buffer.numberOfChannels,length,buffer.sampleRate);for(let c=0;c<buffer.numberOfChannels;c++){const dst=out.getChannelData(c);dst.set(buffer.getChannelData(c).subarray(0,length));const fade=length<buffer.length?Math.min(length,Math.round(.2*buffer.sampleRate)):0;for(let j=0;j<fade;j++)dst[length-fade+j]*=1-j/Math.max(1,fade-1);}return out;}
export function activeVideoNotes(track,beat){return track.events.filter(e=>e.beat<=beat&&e.beat+e.duration>beat);}
export function addVideoLeadIn(buffer,p,o,createBuffer){const t=videoTiming(p,o),rate=buffer.sampleRate,prefix=Math.round(t.prefix*rate),out=createBuffer(2,buffer.length+prefix,rate);for(let ch=0;ch<2;ch++){const dst=out.getChannelData(ch);dst.set(buffer.getChannelData(Math.min(ch,buffer.numberOfChannels-1)),prefix);if(o.countIn){const unit=p.meter==='6/8'?1.5:1;for(let b=0;b<barBeats(p);b+=unit){const start=Math.round((t.title+b*t.seconds)*rate);for(let j=0;j<rate*.055;j++)dst[start+j]+=.14*Math.sin(2*Math.PI*(b===0?1500:1050)*j/rate)*Math.exp(-j/(rate*.012));}}}return out;}
const check=signal=>{if(signal?.aborted)throw new DOMException('Video export cancelled.','AbortError')};
const pause=()=>new Promise(resolve=>setTimeout(resolve,0));
async function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('An instrument image could not load. Please reload and retry.'));im.src=src;});}
export async function videoCapabilities(fps=30){const m=await import('./vendor/mediabunny.mjs');const config={width:W,height:H,frameRate:fps,bitrate:8e6};const [avc,aac,vp9,opus]=await Promise.all([m.canEncodeVideo('avc',config),m.canEncodeAudio('aac',{numberOfChannels:2,sampleRate:44100,bitrate:192000}),m.canEncodeVideo('vp9',config),m.canEncodeAudio('opus',{numberOfChannels:2,sampleRate:44100,bitrate:192000})]);return {mp4:avc&&aac,webm:vp9&&opus};}
function text(ctx,value,x,y,size=30,color='#f4eddb',max=1750){ctx.fillStyle=color;ctx.font=`500 ${size}px "DM Sans", sans-serif`;let s=String(value);while(s.length>1&&ctx.measureText(s).width>max)s=s.slice(0,-2)+'…';ctx.fillText(s,x,y);}
function round(ctx,x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function instrument(ctx,track,im,box,beat,key){const art=ART[track.instrument],inst=getInstrument(track.instrument),[x,y,w,h]=box;const scale=Math.min(w/im.width,h/im.height),iw=im.width*scale,ih=im.height*scale,ox=x+(w-iw)/2,oy=y+(h-ih)/2;ctx.drawImage(im,ox,oy,iw,ih);const ns=notesFor(inst,key),active=activeVideoNotes(track,beat),indices=new Set(active.map(e=>ns.findIndex(n=>n.note===e.note&&(n.shift||0)===(e.shift||0))));ctx.save();ctx.translate(ox,oy);ctx.scale(iw,ih);ctx.fillStyle='#ffdc6e99';for(const [index,shape]of(art.hits||[]).entries()){if(!indices.has(shape.noteIndex??index))continue;ctx.beginPath();if(shape.points){shape.points.forEach(([a,b],n)=>n?ctx.lineTo(a,b):ctx.moveTo(a,b));ctx.closePath()}else if(shape.ellipse){ctx.ellipse(...shape.ellipse,0,0,Math.PI*2)}else if(shape.rect){ctx.rect(...shape.rect)}ctx.fill();}ctx.restore();return active;}
async function notationImage(p,track,first){const start=first*barBeats(p),bars=Math.min(2,p.bars-first),end=start+bars*barBeats(p);const events=notationEvents(scoreProject(p),track,.25).filter(e=>e.beat<end&&e.beat+e.duration>start).map(e=>({...e,beat:Math.max(start,e.beat)-start,duration:Math.min(end,e.beat+e.duration)-Math.max(start,e.beat)}));const el=document.createElement('div');const page={...p,bars,measureOffset:first,sectionMarkers:[],tracks:[{...track,events}],notation:{...p.notation,measures:2,partMeasures:2}};renderPatternScore(el,scoreProject(page),[track.id],.25,{measures:2,continuous:true});const svg=el.querySelector('.staff-music svg');if(!svg)throw Error('Student notation could not be drawn.');svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','1600');svg.setAttribute('height','440');svg.style.width='1600px';svg.style.height='440px';const blob=new Blob([svg.outerHTML],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{return await loadImage(url)}finally{URL.revokeObjectURL(url)}}
export async function createVideoPainter(p,o,canvas){await document.fonts?.ready;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Video canvas is unavailable.');const visible=o.mode==='student'?p.tracks.filter(t=>t.id===o.trackId):p.tracks.filter(t=>o.visibleIds.includes(t.id));if(!visible.length||visible.length>12)throw Error('Choose between 1 and 12 visible parts.');const images=new Map(await Promise.all(visible.map(async t=>[t.id,await loadImage(ART[t.instrument].src)])));const audible=new Set(audibleTracks(p).map(t=>t.id));const scorePages=new Map();
 return async time=>{const s=videoState(p,o,time);ctx.fillStyle='#233c30';ctx.fillRect(0,0,W,H);if(s.phase==='title'){text(ctx,'MALLET & MEASURE',100,170,26,'#d5bb80');text(ctx,p.title,100,450,78,'#fff7e6',1700);text(ctx,p.composer?`Music by ${p.composer}`:'The Orff Ensemble Studio',100,530,32);text(ctx,o.mode==='student'?visible[0].name+' · Student play-along':'Full ensemble performance',100,650,34);if(o.credit)text(ctx,'Made with Mallet & Measure — software by Drew Wichman',100,930,27,'#d5bb80');return;}
 text(ctx,p.title,64,70,40,'#fff7e6',1300);const marker=p.sectionMarkers?.findLast(m=>m.beat<=Math.max(0,s.beat));let status=s.phase==='count'?'Count in':s.phase==='tail'?'Finish':`${marker?.name||'Music'} · Measure ${s.measure+1} / ${p.bars}`;text(ctx,status,64,120,25,'#d5bb80');const unit=p.meter==='6/8'?1.5:1,beats=barBeats(p)/unit;for(let b=0;b<beats;b++){const current=s.phase==='count'?Math.floor((time-s.title)/s.seconds/unit):Math.floor((s.beat%barBeats(p))/unit);round(ctx,1540+b*55,60,36,36,18,current===b&&s.phase!=='tail'?'#edc875':'#647a65');}
 const beat=s.phase==='music'?s.beat:-1;
 if(o.mode==='student'){const t=visible[0],layout=videoStudentLayout(o.layout);round(ctx,55,155,1810,layout.instrumentHeight,18,'#dce1cf');const active=instrument(ctx,t,images.get(t.id),layout.image,beat,p.key);text(ctx,t.name,layout.labelX,layout.labelY,32,'#2a4334',layout.labelWidth);const ns=notesFor(getInstrument(t.instrument),p.key);const labels=active.map(e=>ns.find(n=>n.note===e.note&&(n.shift||0)===(e.shift||0))?.label||'Hit');text(ctx,s.phase==='count'?String(Math.max(1,beats-Math.floor((time-s.title)/s.seconds/unit))):s.phase==='tail'?'Finish':labels.join(' · ')||'Rest',layout.labelX,layout.labelY+80,46,'#2a4334',layout.labelWidth);text(ctx,{ensemble:'Full mix',part:'My part only',accompaniment:'Without my part'}[o.listening],layout.labelX,layout.labelY+150,24,'#425c47',layout.labelWidth);
 round(ctx,55,layout.scoreTop,1810,layout.scoreHeight,14,'#fffef8');text(ctx,s.phase==='count'?'Get ready · Read ahead':s.phase==='tail'?'Finish':`Playing measure ${s.measure+1} · Read ahead`,80,layout.scoreTop+40,23,'#304332');
 const pageWidth=800*layout.notationHeight/220,scroll=videoScoreScroll(p,Math.max(0,s.beat),pageWidth),origin=layout.anchor+pageWidth/4-scroll,firstPage=Math.max(0,Math.floor((75-origin)/pageWidth));
 ctx.save();ctx.beginPath();ctx.rect(75,layout.scoreY,1770,layout.notationHeight);ctx.clip();
 for(let page=firstPage;page*2<p.bars&&origin+page*pageWidth<1845;page++){if(!scorePages.has(page))scorePages.set(page,await notationImage(p,t,page*2));const score=scorePages.get(page);ctx.drawImage(score,origin+page*pageWidth,layout.scoreY,pageWidth,layout.notationHeight);}
 ctx.restore();for(const page of scorePages.keys())if(page<firstPage-1)scorePages.delete(page);
 const pads=getInstrument(t.instrument).pads;if(pads)text(ctx,pads.map((pad,n)=>pad[0]+(pads.length>1?' = '+['bottom','second','middle','fourth','top'][n%5]+' line':'')).join(' · '),80,970,19,'#304332',1700);
 }else{const cols=visible.length<=4?2:visible.length<=6?3:4,rows=Math.ceil(visible.length/cols),cw=1790/cols,ch=800/rows;visible.forEach((t,n)=>{const x=55+(n%cols)*cw,y=155+Math.floor(n/cols)*ch;const partBeat=audible.has(t.id)?beat:-1,active=activeVideoNotes(t,partBeat);round(ctx,x,y,cw-18,ch-18,14,active.length?'#e9dfb8':'#dce1cf');text(ctx,t.name,x+20,y+36,25,'#304332',cw-60);instrument(ctx,t,images.get(t.id),[x+15,y+48,cw-48,ch-105],partBeat,p.key);text(ctx,active.length?'Playing':!audible.has(t.id)?'Muted':s.phase==='music'?'Rest':s.phase==='count'?'Ready':'Finish',x+20,y+ch-36,19,'#405a46',cw-60);});}
 if(o.credit)text(ctx,'Made with Mallet & Measure — software by Drew Wichman',64,1040,21,'#d5bb80',1400);text(ctx,'Mallet & Measure',1550,1040,21,'#d5bb80',310);round(ctx,55,1000,1810,6,3,'#526b56');if(s.beat>=0)round(ctx,55,1000,1810*Math.min(1,s.beat/totalBeats(p)),6,3,'#d5bb80');
 };
}
export async function exportVideo(p,o,engine,{signal,onProgress=()=>{},canvas=document.createElement('canvas')}={}){
 check(signal);if(o.preview)p=videoPreviewProject(p);if(totalBeats(p)*60/p.bpm>300)throw Error('Choose a section or song up to five minutes for video export.');const caps=await videoCapabilities(o.fps);if(!caps[o.format])throw Error(o.format==='mp4'?'MP4 encoding is unavailable in this browser. Choose WebM if available, or use a browser with H.264 and AAC encoding.':'WebM encoding is unavailable in this browser.');check(signal);
 canvas.width=W;canvas.height=H;onProgress(.02,'Preparing instrument pictures…');const paint=await createVideoPainter(p,o,canvas);check(signal);onProgress(.05,'Rendering your instrument samples and mix…');let buffer=await engine.render(videoMix(p,o));check(signal);const makeBuffer=(...args)=>engine.ctx.createBuffer(...args);if(o.preview)buffer=trimVideoPreviewAudio(buffer,p,makeBuffer);const audio=addVideoLeadIn(buffer,p,o,makeBuffer);const m=await import('./vendor/mediabunny.mjs'),target=new m.BufferTarget(),output=new m.Output({format:o.format==='mp4'?new m.Mp4OutputFormat({fastStart:'in-memory'}):new m.WebMOutputFormat(),target});const video=new m.CanvasSource(canvas,{codec:o.format==='mp4'?'avc':'vp9',bitrate:8e6,keyFrameInterval:2}),sound=new m.AudioBufferSource({codec:o.format==='mp4'?'aac':'opus',bitrate:192000});output.addVideoTrack(video,{frameRate:o.fps});output.addAudioTrack(sound);output.setMetadataTags({title:p.title,artist:p.composer,comment:'Created with Mallet & Measure'});
 try{await output.start();check(signal);await sound.add(audio);sound.close();const frames=Math.ceil(audio.duration*o.fps);for(let frame=0;frame<frames;frame++){check(signal);await paint(frame/o.fps);await video.add(frame/o.fps,Math.min(1/o.fps,audio.duration-frame/o.fps));if(frame%15===0){onProgress(.15+.8*frame/frames,`Rendering video · ${Math.round(frame/frames*100)}%`);await pause();}}video.close();check(signal);onProgress(.97,'Finishing video file…');await output.finalize();check(signal);return new Blob([target.buffer],{type:o.format==='mp4'?'video/mp4':'video/webm'});}catch(e){await output.cancel().catch(()=>{});throw e;}
}
